using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using verii_wms_api_v2.Modules.WarehouseOutbound.Domain;
using verii_wms_api_v2.Shared.Infrastructure;

namespace verii_wms_api_v2.Modules.WarehouseOutbound.Infrastructure;

public sealed class WarehouseOutboundHeaderConfiguration:BaseEntityConfiguration<WarehouseOutboundHeader>{
 protected override void ConfigureEntity(EntityTypeBuilder<WarehouseOutboundHeader>b){b.ToTable("RII_WO_HEADER");b.Property(x=>x.DocumentNo).HasMaxLength(50).IsRequired();b.Property(x=>x.CustomerCodeSnapshot).HasMaxLength(100).IsRequired();b.Property(x=>x.CustomerNameSnapshot).HasMaxLength(300);b.Property(x=>x.ExternalReferenceNo).HasMaxLength(100);b.Property(x=>x.WaybillNo).HasMaxLength(50);b.Property(x=>x.CarrierCode).HasMaxLength(50);b.Property(x=>x.CarrierName).HasMaxLength(200);b.Property(x=>x.VehiclePlate).HasMaxLength(20);b.Property(x=>x.TrailerPlate).HasMaxLength(20);b.Property(x=>x.DriverName).HasMaxLength(200);b.Property(x=>x.SealNo).HasMaxLength(50);b.Property(x=>x.TrackingNo).HasMaxLength(100);b.Property(x=>x.Description).HasMaxLength(2000);b.Property(x=>x.ReservationPolicy).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.PackingPolicy).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.ShortagePolicy).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.OverPickPolicy).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.MinimumFulfillmentPercent).HasPrecision(9,4);b.Property(x=>x.OverPickTolerancePercent).HasPrecision(9,4);b.Property(x=>x.RowVersion).IsRowVersion();b.HasIndex(x=>new{x.BranchCode,x.DocumentNo}).IsUnique();b.HasIndex(x=>x.CorrelationId).IsUnique();b.HasIndex(x=>new{x.BranchCode,x.Status,x.PlannedWarehouseOutboundAtUtc});}}
public sealed class WarehouseOutboundSourceDocumentConfiguration:BaseEntityConfiguration<WarehouseOutboundSourceDocument>{protected override void ConfigureEntity(EntityTypeBuilder<WarehouseOutboundSourceDocument>b){b.ToTable("RII_WO_SOURCE_DOCUMENT");b.Property(x=>x.SourceDocumentType).HasMaxLength(50).IsRequired();b.Property(x=>x.ExternalDocumentNo).HasMaxLength(100).IsRequired();b.Property(x=>x.ExternalDocumentId).HasMaxLength(100);b.Property(x=>x.ExternalStatus).HasMaxLength(50);b.HasOne(x=>x.Header).WithMany(x=>x.SourceDocuments).HasForeignKey(x=>x.WarehouseOutboundHeaderId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.WarehouseOutboundHeaderId,x.SourceDocumentType,x.ExternalDocumentNo}).IsUnique();}}
public sealed class WarehouseOutboundLineConfiguration:BaseEntityConfiguration<WarehouseOutboundLine>{protected override void ConfigureEntity(EntityTypeBuilder<WarehouseOutboundLine>b){b.ToTable("RII_WO_LINE",t=>t.HasCheckConstraint("CK_RII_WO_LINE_QTY","[RequestedQuantity] > 0 AND [ReservedQuantity] >= 0 AND [PickedQuantity] >= 0 AND [PackedQuantity] >= 0 AND [LoadedQuantity] >= 0 AND [ShippedQuantity] >= 0 AND [ShortClosedQuantity] >= 0"));b.Property(x=>x.StockCodeSnapshot).HasMaxLength(100).IsRequired();b.Property(x=>x.StockNameSnapshot).HasMaxLength(300);b.Property(x=>x.YapCodeSnapshot).HasMaxLength(100);b.Property(x=>x.UnitCode).HasMaxLength(20).IsRequired();foreach(var p in new[]{nameof(WarehouseOutboundLine.RequestedQuantity),nameof(WarehouseOutboundLine.ReservedQuantity),nameof(WarehouseOutboundLine.PickedQuantity),nameof(WarehouseOutboundLine.PackedQuantity),nameof(WarehouseOutboundLine.LoadedQuantity),nameof(WarehouseOutboundLine.ShippedQuantity),nameof(WarehouseOutboundLine.ShortClosedQuantity)})b.Property(p).HasPrecision(20,6);b.Property(x=>x.Description).HasMaxLength(1000);b.Property(x=>x.RowVersion).IsRowVersion();b.HasOne(x=>x.Header).WithMany(x=>x.Lines).HasForeignKey(x=>x.WarehouseOutboundHeaderId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.WarehouseOutboundHeaderId,x.LineNo}).IsUnique();}}
public sealed class WarehouseOutboundLineSourceConfiguration:BaseEntityConfiguration<WarehouseOutboundLineSource>{protected override void ConfigureEntity(EntityTypeBuilder<WarehouseOutboundLineSource>b){b.ToTable("RII_WO_LINE_SOURCE");b.Property(x=>x.ExternalLineId).HasMaxLength(100).IsRequired();b.Property(x=>x.ExternalStockCode).HasMaxLength(100).IsRequired();b.Property(x=>x.ExternalYapCode).HasMaxLength(100);b.Property(x=>x.UnitCode).HasMaxLength(20).IsRequired();b.Property(x=>x.OrderedQuantity).HasPrecision(20,6);b.Property(x=>x.PreviouslyShippedQuantity).HasPrecision(20,6);b.Property(x=>x.AllocatedQuantity).HasPrecision(20,6);b.HasOne(x=>x.Line).WithMany(x=>x.Sources).HasForeignKey(x=>x.WarehouseOutboundLineId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.SourceDocument).WithMany(x=>x.LineSources).HasForeignKey(x=>x.WarehouseOutboundSourceDocumentId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.WarehouseOutboundLineId,x.WarehouseOutboundSourceDocumentId,x.ExternalLineId}).IsUnique();b.HasIndex(x=>new{x.WarehouseOutboundSourceDocumentId,x.ExternalLineId});}}
public sealed class WarehouseOutboundTrackingConfiguration:BaseEntityConfiguration<WarehouseOutboundTracking>{protected override void ConfigureEntity(EntityTypeBuilder<WarehouseOutboundTracking>b){b.ToTable("RII_WO_TRACKING",t=>t.HasCheckConstraint("CK_RII_WO_TRACKING_QTY","[PlannedQuantity] > 0 AND [ReservedQuantity] >= 0 AND [PickedQuantity] >= 0 AND [PackedQuantity] >= 0 AND [LoadedQuantity] >= 0 AND [ShippedQuantity] >= 0"));b.Property(x=>x.HandlingUnitNo).HasMaxLength(100);b.Property(x=>x.ContainerNo).HasMaxLength(100);b.Property(x=>x.LotNo).HasMaxLength(100);b.Property(x=>x.SerialNo).HasMaxLength(200);foreach(var p in new[]{nameof(WarehouseOutboundTracking.PlannedQuantity),nameof(WarehouseOutboundTracking.ReservedQuantity),nameof(WarehouseOutboundTracking.PickedQuantity),nameof(WarehouseOutboundTracking.PackedQuantity),nameof(WarehouseOutboundTracking.LoadedQuantity),nameof(WarehouseOutboundTracking.ShippedQuantity)})b.Property(p).HasPrecision(20,6);b.Property(x=>x.RowVersion).IsRowVersion();b.HasOne(x=>x.Line).WithMany(x=>x.Trackings).HasForeignKey(x=>x.WarehouseOutboundLineId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.WarehouseOutboundLineId,x.SerialNo});}}
public sealed class WarehouseOutboundTaskConfiguration:BaseEntityConfiguration<WarehouseOutboundTask>{protected override void ConfigureEntity(EntityTypeBuilder<WarehouseOutboundTask>b){b.ToTable("RII_WO_TASK");b.Property(x=>x.TaskNo).HasMaxLength(50).IsRequired();b.Property(x=>x.RowVersion).IsRowVersion();b.HasOne(x=>x.Header).WithMany(x=>x.Tasks).HasForeignKey(x=>x.WarehouseOutboundHeaderId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.BranchCode,x.TaskNo}).IsUnique();}}
public sealed class WarehouseOutboundTaskLineConfiguration:BaseEntityConfiguration<WarehouseOutboundTaskLine>{protected override void ConfigureEntity(EntityTypeBuilder<WarehouseOutboundTaskLine>b){b.ToTable("RII_WO_TASK_LINE",t=>t.HasCheckConstraint("CK_RII_WO_TASK_LINE_QTY","[PlannedQuantity] > 0 AND [ProcessedQuantity] >= 0"));b.Property(x=>x.PlannedQuantity).HasPrecision(20,6);b.Property(x=>x.ProcessedQuantity).HasPrecision(20,6);b.Property(x=>x.RowVersion).IsRowVersion();b.HasOne(x=>x.Task).WithMany(x=>x.Lines).HasForeignKey(x=>x.WarehouseOutboundTaskId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Line).WithMany(x=>x.TaskLines).HasForeignKey(x=>x.WarehouseOutboundLineId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.WarehouseOutboundTaskId,x.WarehouseOutboundLineId}).IsUnique();}}
public sealed class WarehouseOutboundTaskAssignmentConfiguration:BaseEntityConfiguration<WarehouseOutboundTaskAssignment>{protected override void ConfigureEntity(EntityTypeBuilder<WarehouseOutboundTaskAssignment>b){b.ToTable("RII_WO_TASK_ASSIGNMENT");b.HasOne(x=>x.Task).WithMany(x=>x.Assignments).HasForeignKey(x=>x.WarehouseOutboundTaskId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.WarehouseOutboundTaskId,x.UserId}).IsUnique();}}
public sealed class WarehouseOutboundStatusHistoryConfiguration:BaseEntityConfiguration<WarehouseOutboundStatusHistory>{protected override void ConfigureEntity(EntityTypeBuilder<WarehouseOutboundStatusHistory>b){b.ToTable("RII_WO_STATUS_HISTORY");b.Property(x=>x.FromStatus).HasMaxLength(50);b.Property(x=>x.ToStatus).HasMaxLength(50).IsRequired();b.Property(x=>x.Description).HasMaxLength(1000);b.HasOne(x=>x.Header).WithMany(x=>x.StatusHistory).HasForeignKey(x=>x.WarehouseOutboundHeaderId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.WarehouseOutboundHeaderId,x.ChangedAtUtc});}}
public sealed class WarehouseOutboundPolicyConfiguration:BaseEntityConfiguration<WarehouseOutboundPolicy>{protected override void ConfigureEntity(EntityTypeBuilder<WarehouseOutboundPolicy>b){b.ToTable("RII_WO_POLICIES",t=>{t.HasCheckConstraint("CK_RII_WO_POLICY_FULFILLMENT","[MinimumFulfillmentPercent] >= 0 AND [MinimumFulfillmentPercent] <= 100");t.HasCheckConstraint("CK_RII_WO_POLICY_OVERPICK","[OverPickTolerancePercent] >= 0 AND [OverPickTolerancePercent] <= 100");});b.Property(x=>x.PolicyKey).HasMaxLength(30).IsRequired();b.Property(x=>x.ReservationPolicy).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.PackingPolicy).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.ShortagePolicy).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.OverPickPolicy).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.MinimumFulfillmentPercent).HasPrecision(9,4);b.Property(x=>x.OverPickTolerancePercent).HasPrecision(9,4);b.Property(x=>x.RowVersion).IsRowVersion();b.HasIndex(x=>new{x.BranchCode,x.PolicyKey}).IsUnique().HasFilter("[IsDeleted] = 0");}}
